interface LeaderNodeData {
  id: string
  name: string
  emoji: string
  title: string
  model: string
  tier: string
  phaseColor: string
  description: string
  dimmed: boolean
  [key: string]: unknown
}

function toMemberInfo(node: OrgChartNode): MemberInfo {
  const { emoji, cleanName } = extractEmoji(node.name)
  return {
    id: node.id,
    name: cleanName,
    emoji,
    title: node.title,
    model: node.model,
    tier: node.tier,
    phaseColor: node.departmentColor || node.phaseColor,
    reportsTo: node.reportsTo,
    dimmed: false,
    level: node.level ?? null,
    levelTitle: node.levelTitle ?? null,
    yearsOfExperience: node.yearsOfExperience ?? null,
    status: node.status,
  }
}

function computeDepartmentLayout(
  allNodes: OrgChartNode[],
  departmentList: OrgChartData['departments'] = [],
): {
  rfNodes: Node[]
  rfEdges: Edge[]
} {
  // Rex (and anyone else without a manager) is a top leader. Everyone else
  // gets placed in their department column.
  const leaders = allNodes.filter(n => !n.reportsTo)
  const leaderIds = new Set(leaders.map(l => l.id))
  const members = allNodes.filter(n => !leaderIds.has(n.id))

  // Build a member-by-department lookup
  const byDepartment = new Map<string, OrgChartNode[]>()
  for (const m of members) {
    // Use '__unassigned__' so agents without a department are grouped explicitly
    // rather than silently dumped into 'engineering'
    const dept = m.department || '__unassigned__'
    if (!byDepartment.has(dept)) byDepartment.set(dept, [])
    byDepartment.get(dept)!.push(m)
  }

  // Departments to render — use the server-provided ordered list, skipping
  // any department whose only members are already rendered as leader nodes
  // (i.e. departments that are empty after separating out leaders).
  // This is data-driven — no hardcoded 'executive' string.
  const departments = departmentList
    .map(d => ({
      id: d.id,
      label: d.label,
      color: d.color,
      head: d.head,
      members: (byDepartment.get(d.id) || []).slice().sort((a, b) => {
        // Department head first, then leaders, then by level desc, then name
        if (a.id === d.head) return -1
        if (b.id === d.head) return 1
        if (a.tier === 'leadership' && b.tier !== 'leadership') return -1
        if (b.tier === 'leadership' && a.tier !== 'leadership') return 1
        if ((b.level || 0) !== (a.level || 0)) return (b.level || 0) - (a.level || 0)
        return a.name.localeCompare(b.name)
      }),
    }))
    .filter(d => d.members.length > 0)

  // If any registered agents have no department assigned, add a virtual "Unassigned" column
  const unassignedMembers = byDepartment.get('__unassigned__') || []
  if (unassignedMembers.length > 0) {
    departments.push({
      id: '__unassigned__',
      label: 'Unassigned',
      color: '#6b7280',
      head: '',
      members: unassignedMembers.slice().sort((a, b) => a.name.localeCompare(b.name)),
    })
  }

  // Compute row widths
  const deptsRowWidth = departments.length * DEPT_WIDTH
    + Math.max(0, departments.length - 1) * DEPT_ROW_GAP
  const leadersRowWidth = leaders.length * LEADER_WIDTH
    + Math.max(0, leaders.length - 1) * LEADER_LEADER_GAP
  const canvasWidth = Math.max(deptsRowWidth, leadersRowWidth)

  // Y positions
  const leadersY = 0
  const deptsY = LEADER_HEIGHT + LEADER_DEPT_GAP

  const rfNodes: Node[] = []
  const rfEdges: Edge[] = []

  // Place leader nodes (Rex + any other top-level agent)
  const leadersStartX = (canvasWidth - leadersRowWidth) / 2
  const rexId = leaders[0]?.id
  leaders.forEach((leader, i) => {
    const x = leadersStartX + i * (LEADER_WIDTH + LEADER_LEADER_GAP)
    const { emoji, cleanName } = extractEmoji(leader.name)
    rfNodes.push({
      id: leader.id,
      type: 'orgLeader',
      position: { x, y: leadersY },
      data: {
        id: leader.id,
        name: cleanName,
        emoji,
        title: leader.title,
        model: leader.model,
        tier: leader.tier,
        phaseColor: leader.departmentColor || leader.phaseColor,
        description: leader.description,
        dimmed: false,
      } satisfies LeaderNodeData,
    })
  })

  // Place department columns
  const deptsStartX = (canvasWidth - deptsRowWidth) / 2
  departments.forEach((dept, i) => {
    const x = deptsStartX + i * (DEPT_WIDTH + DEPT_ROW_GAP)
    const memberCount = dept.members.length
    const height = DEPT_HEADER_HEIGHT
      + DEPT_PADDING_Y * 2
      + memberCount * MEMBER_ROW_HEIGHT
      + Math.max(0, memberCount - 1) * MEMBER_ROW_GAP

    rfNodes.push({
      id: `dept-${dept.id}`,
      type: 'orgDept',
      position: { x, y: deptsY },
      data: {
        // Reuse phase* field names so OrgDepartmentNode renders unchanged
        phase: dept.id,
        phaseLabel: dept.label,
        phaseColor: dept.color,
        members: dept.members.map(toMemberInfo),
        width: DEPT_WIDTH,
        height,
        dimmed: false,
      } satisfies DepartmentNodeData,
    })

    // Edge from Rex to each department
    if (rexId) {
      rfEdges.push({
        id: `e-${rexId}-dept-${dept.id}`,
        source: rexId,
        target: `dept-${dept.id}`,
        type: 'smoothstep',
        style: {
          stroke: dept.color,
          strokeWidth: 2.5,
          opacity: 0.55,
        },
      })
    }
  })

  return { rfNodes, rfEdges }
}

